# 直线 ax+by+c=0
def line_intersect(l1, l2):
  a1,b1,c1 = l1; a2,b2,c2 = l2
  det = a1*b2 - a2*b1
  if abs(det) < EPS: return PARALLEL   # 是否重合再查
  x = -(c1*b2 - c2*b1)/det
  y = -(a1*c2 - a2*c1)/det
  return (x,y)

def line_from_two_points(p, q):
  a = q.y - p.y; b = p.x - q.x; c = -a*p.x - b*p.y
  return (a,b,c)
